import itertools
import string
import hashlib
import time

class PasswordCracker:
    def __init__(self):
        self.charset = string.ascii_lowercase + string.digits

    def generate_passwords(self, max_length):
        """Generate password combinations"""
        for length in range(1, max_length + 1):
            for password in itertools.product(self.charset, repeat=length):
                yield ''.join(password)

    def hash_password(self, password, method='md5'):
        """Hash a password using specified method"""
        if method == 'md5':
            return hashlib.md5(password.encode()).hexdigest()
        elif method == 'sha256':
            return hashlib.sha256(password.encode()).hexdigest()

    def crack_password(self, target_hash, max_length=6, hash_method='md5'):
        """Attempt to crack a password hash"""
        start_time = time.time()
        attempts = 0

        for password in self.generate_passwords(max_length):
            attempts += 1
            current_hash = self.hash_password(password, hash_method)

            if current_hash == target_hash:
                end_time = time.time()
                return {
                    'password': password,
                    'attempts': attempts,
                    'time_taken': end_time - start_time
                }

        return None

    def dictionary_attack(self, target_hash, dictionary_file, hash_method='md5'):
        """Perform a dictionary attack"""
        start_time = time.time()
        attempts = 0

        try:
            with open(dictionary_file, 'r') as file:
                for line in file:
                    password = line.strip()
                    attempts += 1

                    current_hash = self.hash_password(password, hash_method)

                    if current_hash == target_hash:
                        end_time = time.time()
                        return {
                            'password': password,
                            'attempts': attempts,
                            'time_taken': end_time - start_time
                        }
        except FileNotFoundError:
            print(f"Dictionary file {dictionary_file} not found.")

        return None

# Example usage
def main():
    cracker = PasswordCracker()

    # Example hash to crack (MD5)
    target_hash = '5f4dcc3b5aa765d61d8327deb882cf99'  # password: 'password'

    print("Brute Force Attack:")
    result = cracker.crack_password(target_hash)

    if result:
        print(f"Password found: {result['password']}")
        print(f"Attempts: {result['attempts']}")
        print(f"Time taken: {result['time_taken']:.2f} seconds")
    else:
        print("Password not found")

    print("\nDictionary Attack:")
    dict_result = cracker.dictionary_attack(
        target_hash, 
        'common_passwords.txt'  # You'd need to provide this file
    )

    if dict_result:
        print(f"Password found: {dict_result['password']}")
        print(f"Attempts: {dict_result['attempts']}")
        print(f"Time taken: {dict_result['time_taken']:.2f} seconds")
    else:
        print("Password not found in dictionary")

if __name__ == "__main__":
    main()
